// embedded n8n/lib/agent_config.js (drift-proof; test asserts equality)
// agent_config.js — Stage 4 central configuration contract (B1).
//
// ONE place resolves the entire agent runtime config from environment variables + safe defaults,
// so the operator never hand-edits a Spreadsheet ID (or any limit/flag) inside individual nodes.
// The orchestrator calls resolveConfig() once and passes the resolved object downstream; every other
// workflow receives config from the request record instead of carrying its own copy.
//
// NO secrets live here or in workflow JSON. Credentials (Google/Telegram/Claude/Apify) stay in the
// n8n credential store; this module only resolves NON-secret runtime settings + the spreadsheet id
// (an id, not a secret) from $env. In a Code node call it as resolveConfig($env) — the harness shims
// $env as {} so the same code runs offline.

function str(v) { return v == null ? '' : String(v).trim(); }
function num(v, d) { const n = Number(v); return isFinite(n) && str(v) !== '' ? n : d; }
function bool(v, d) {
  if (v === true) return true;
  if (v === false) return false;
  const s = str(v).toLowerCase();
  if (s === 'true' || s === 'yes' || s === '1') return true;
  if (s === 'false' || s === 'no' || s === '0') return false;
  return d;
}
function list(v) { return str(v).split(/[\s,;]+/).filter(Boolean); }

// Production-safe defaults: fail-closed (approval + source-health required), website-only allowlist,
// LLM features OFF, tight budgets. Everything is overridable by env or explicit override.
const DEFAULTS = {
  spreadsheet_id: '',
  telegram_allowed_user_ids: [],
  max_sources_per_request: 3,
  max_items_per_source: 25,
  max_external_calls: 40,
  source_budget_usd: 0.20,
  llm_budget_usd: 0.50,
  default_region: 'Москва/МО',
  default_niche: 'credit_brokerage',
  source_allowlist: ['website'],
  require_approval: true,
  require_source_health: true,
  enable_llm_planner: false,
  enable_llm_summary: false,
  report_data_mode: 'live',
  // ---- Stage 4 free-path / zero-paid-call guards (all fail-closed) -------------------------------------------
  // Telegram conversation is allowed; every PAID external action is OFF by default. The free path runs the full
  // conversation -> plan -> approval -> persistence loop while making zero paid calls. `max_external_calls` (above)
  // is the master kill-switch: 0 means no paid source/LLM call can occur even after approval.
  timezone: 'Europe/Moscow',
  // WF18-CONFIG-001: the Telegram ingress is fail-closed. The bot does NOTHING (no parse, no Sheets, no send)
  // until the operator explicitly sets MS_ENABLE_TELEGRAM=true. WF18 branches on this as a HARD ingress gate.
  enable_telegram: false,
  enable_external_actions: false,   // master switch for any paid collection/analysis
  enable_claude: false,             // Claude (planner/summary) only when explicitly enabled
  enable_apify: false,
  enable_firecrawl: false,
  enable_vk: false,
  monitoring_enabled: false,
  weekly_digest_enabled: false
};

// Map env var -> resolved config. Unknown/blank env falls back to DEFAULTS; explicit overrides win last.
function resolveConfig(env, overrides) {
  env = env || {};
  overrides = overrides || {};
  const allowedUsers = list(env.MS_TELEGRAM_ALLOWED_USER_IDS);
  const allowlist = list(env.MS_SOURCE_ALLOWLIST).map(s => s.toLowerCase());
  const cfg = {
    spreadsheet_id: str(env.MS_SPREADSHEET_ID) || DEFAULTS.spreadsheet_id,
    telegram_allowed_user_ids: (allowedUsers.length ? allowedUsers : DEFAULTS.telegram_allowed_user_ids).map(String),
    max_sources_per_request: num(env.MS_MAX_SOURCES, DEFAULTS.max_sources_per_request),
    max_items_per_source: num(env.MS_MAX_ITEMS_PER_SOURCE, DEFAULTS.max_items_per_source),
    max_external_calls: num(env.MS_MAX_EXTERNAL_CALLS, DEFAULTS.max_external_calls),
    source_budget_usd: num(env.MS_SOURCE_BUDGET_USD, DEFAULTS.source_budget_usd),
    llm_budget_usd: num(env.MS_LLM_BUDGET_USD, DEFAULTS.llm_budget_usd),
    default_region: str(env.MS_DEFAULT_REGION) || DEFAULTS.default_region,
    default_niche: str(env.MS_DEFAULT_NICHE) || DEFAULTS.default_niche,
    source_allowlist: allowlist.length ? allowlist : DEFAULTS.source_allowlist.slice(),
    require_approval: bool(env.MS_REQUIRE_APPROVAL, DEFAULTS.require_approval),
    require_source_health: bool(env.MS_REQUIRE_SOURCE_HEALTH, DEFAULTS.require_source_health),
    enable_llm_planner: bool(env.MS_ENABLE_LLM_PLANNER, DEFAULTS.enable_llm_planner),
    enable_llm_summary: bool(env.MS_ENABLE_LLM_SUMMARY, DEFAULTS.enable_llm_summary),
    report_data_mode: str(env.MS_REPORT_DATA_MODE) || DEFAULTS.report_data_mode,
    timezone: str(env.MS_TIMEZONE) || DEFAULTS.timezone,
    enable_telegram: bool(env.MS_ENABLE_TELEGRAM, DEFAULTS.enable_telegram),
    enable_external_actions: bool(env.MS_ENABLE_EXTERNAL_ACTIONS, DEFAULTS.enable_external_actions),
    enable_claude: bool(env.MS_ENABLE_CLAUDE, DEFAULTS.enable_claude),
    enable_apify: bool(env.MS_ENABLE_APIFY, DEFAULTS.enable_apify),
    enable_firecrawl: bool(env.MS_ENABLE_FIRECRAWL, DEFAULTS.enable_firecrawl),
    enable_vk: bool(env.MS_ENABLE_VK, DEFAULTS.enable_vk),
    monitoring_enabled: bool(env.MS_MONITORING_ENABLED, DEFAULTS.monitoring_enabled),
    weekly_digest_enabled: bool(env.MS_WEEKLY_DIGEST_ENABLED, DEFAULTS.weekly_digest_enabled)
  };
  for (const k in overrides) {
    if (Object.prototype.hasOwnProperty.call(overrides, k)) cfg[k] = overrides[k];
  }
  // fail-closed reconciliation: Claude master switch gates the LLM features; the external-actions master switch
  // (or a zero call ceiling) forces the effective paid-call budget to zero so no approval can spend.
  if (!cfg.enable_claude) { cfg.enable_llm_planner = false; cfg.enable_llm_summary = false; }
  // WF19-LLM-001: there is NO in-graph Claude intent-classifier node in WF18, so the intent router's guarded
  // LLM branch is unreachable by construction. Pin enable_llm_intent=false in the resolved config so the router
  // always resolves deterministically or asks ONE clarification — we never advertise a classification path that
  // cannot run. (The router lib still supports the branch for a future, explicitly-wired classifier.)
  cfg.enable_llm_intent = false;
  cfg.zero_paid_mode = (cfg.enable_external_actions !== true) || (Number(cfg.max_external_calls) <= 0);
  cfg.effective_max_external_calls = cfg.zero_paid_mode ? 0 : Number(cfg.max_external_calls);
  // completeness check the orchestrator surfaces in the execution summary — never starts paid work blind
  cfg.missing = [];
  if (!cfg.spreadsheet_id) cfg.missing.push('MS_SPREADSHEET_ID');
  if (!cfg.telegram_allowed_user_ids.length) cfg.missing.push('MS_TELEGRAM_ALLOWED_USER_IDS');
  cfg.config_complete = cfg.missing.length === 0;
  return cfg;
}

function isAllowedUser(cfg, userId) {
  return ((cfg && cfg.telegram_allowed_user_ids) || []).indexOf(String(userId)) >= 0;
}
function sourceAllowed(cfg, source) {
  return ((cfg && cfg.source_allowlist) || []).indexOf(String(source).toLowerCase()) >= 0;
}
// true only when a PAID external action may run: external actions enabled AND a positive call ceiling.
// This is the single fail-closed predicate the orchestrator/monitor consult before any paid call.
function paidCallsAllowed(cfg) {
  return !!(cfg && cfg.enable_external_actions === true && Number(cfg.max_external_calls) > 0);
}
// per-collector gate: paid calls must be globally allowed AND the specific collector enabled AND on the allowlist.
function collectorEnabled(cfg, source) {
  if (!paidCallsAllowed(cfg)) return false;
  const s = String(source).toLowerCase();
  const flag = { website: 'enable_firecrawl', firecrawl: 'enable_firecrawl', apify: 'enable_apify', avito: 'enable_apify', vk: 'enable_vk' }[s];
  return sourceAllowed(cfg, s) && (flag ? cfg[flag] === true : false);
}
function llmAllowed(cfg) { return !!(cfg && cfg.enable_claude === true && (cfg.enable_llm_planner === true || cfg.enable_llm_summary === true)); }
// machine-readable free-path snapshot for the execution summary / tests.
function freePathStatus(cfg) {
  return {
    zero_paid_mode: !!(cfg && cfg.zero_paid_mode),
    enable_telegram: !!(cfg && cfg.enable_telegram),
    paid_calls_allowed: paidCallsAllowed(cfg),
    llm_allowed: llmAllowed(cfg),
    effective_max_external_calls: cfg ? Number(cfg.effective_max_external_calls) : 0,
    collectors: { firecrawl: collectorEnabled(cfg, 'website'), apify: collectorEnabled(cfg, 'apify'), vk: collectorEnabled(cfg, 'vk') }
  };
}
// --- end embedded agent_config ---

// --- node driver ---
var __env=(typeof $env!=='undefined'&&$env)?$env:{};
return [{json:resolveConfig(__env)}];

// embedded n8n/lib/orchestration_policy.js (drift-proof; test asserts equality)
// orchestration_policy.js — Part 7: conversation-aware reuse vs. collect decision.
//
// A follow-up turn must not blindly repeat paid collection. Before any external call the orchestrator decides:
// can existing evidence answer this? is the evidence too old? did the user explicitly ask to refresh? does the
// new action need a source we have not collected? The decision (and its reason) is persisted so the operator
// can see why a paid call did or did not happen. Standalone + deterministic.

function str(v) { return v == null ? '' : String(v).trim(); }
function low(v) { return str(v).toLowerCase(); }
function num(v, d) { const n = Number(v); return isFinite(n) ? n : (d === undefined ? 0 : d); }

// Intents that are answerable purely from stored context (no external call).
const CONTEXT_ANSWERABLE = ['report_followup', 'generate_ideas', 'compare_periods'];

function freshnessAgeDays(collectedAt, now) {
  const t0 = Date.parse(str(collectedAt)); const t1 = Date.parse(str(now)) || Date.now();
  if (!isFinite(t0)) return Infinity;
  return Math.max(0, (t1 - t0) / 86400000);
}

// Returns { action: 'reuse'|'collect'|'extend', reason, needs_external_call, target_sources }.
function reuseDecision(p) {
  p = p || {};
  const intent = p.intent || {};
  const intentId = low(intent.intent);
  const ctx = p.ctx || {};
  const cfg = p.cfg || {};
  const now = p.now;
  const hasReport = !!(ctx.last_report || ctx.last_report_id);
  const maxAge = num(cfg.evidence_max_age_days, 7);
  const ageDays = freshnessAgeDays(ctx.last_collected_at, now);
  const explicitRefresh = (intent.entities && intent.entities.refresh === true) || intentId === 'rerun_request';
  const requestedPlatforms = (intent.entities && intent.entities.platforms) || [];
  const collected = (ctx.collected_platforms || ['website']).map(low);

  // 1. pure context-answerable intents never spend (if we have a report)
  if (CONTEXT_ANSWERABLE.indexOf(intentId) >= 0) {
    if (hasReport) return mk('reuse', 'answerable_from_last_report', false, []);
    return mk('collect', 'no_report_yet', true, ['website']);
  }
  // 2. explicit refresh always collects fresh
  if (explicitRefresh) return mk('collect', 'explicit_refresh_requested', true, requestedPlatforms.length ? requestedPlatforms : ['website']);
  // 3. deep analysis on existing competitors
  if (intentId === 'deep_competitor_analysis') {
    const newPlatforms = requestedPlatforms.map(low).filter(pl => collected.indexOf(pl) < 0);
    if (hasReport && ageDays <= maxAge && newPlatforms.length === 0) return mk('reuse', 'fresh_evidence_covers_request', false, []);
    if (hasReport && newPlatforms.length > 0) return mk('extend', 'new_platform_requested', true, newPlatforms);
    if (hasReport && ageDays > maxAge) return mk('collect', 'evidence_stale', true, requestedPlatforms.length ? requestedPlatforms : ['website']);
    return mk('collect', 'no_prior_evidence', true, requestedPlatforms.length ? requestedPlatforms : ['website']);
  }
  // 4. source management never spends on collection
  if (intentId === 'add_source' || intentId === 'manage_sources') return mk('reuse', 'source_management_no_collection', false, []);
  // 5. default: a fresh search collects
  return mk('collect', 'new_search', true, requestedPlatforms.length ? requestedPlatforms : ['website']);
}

function mk(action, reason, needsCall, targets) {
  return { action: action, reason: reason, needs_external_call: !!needsCall, target_sources: (targets || []).map(low) };
}

// Persistable record for the orchestration_decisions tab.
function decisionRecord(decision, ids) {
  ids = ids || {};
  return {
    agent_request_id: str(ids.agent_request_id), conversation_id: str(ids.conversation_id),
    intent: str(ids.intent), action: str(decision.action), reason: str(decision.reason),
    needs_external_call: !!decision.needs_external_call, target_sources: (decision.target_sources || []).join(','),
    ts: str(ids.ts)
  };
}
// --- end embedded orchestration_policy ---

// --- node driver ---
function callerInput(){try{var __t=$('When Called by Agent').first().json;if(__t&&Object.keys(__t).length)return __t;}catch(e){}return $json||{};}
var cfg=$('Resolve Agent Config').first().json;
var ci=callerInput();
var inp;
if(ci&&ci.request){inp=ci;}else{var st=String(ci.state||'approved');inp={request:{agent_request_id:String(ci.agent_request_id||'req'),chat_id:String(ci.chat_id||''),owner_user_id:String(ci.owner_user_id||''),state:st,approved:st==='approved',data_mode:String(ci.data_mode||'live'),plan_id:String(ci.plan_id||''),plan_hash:String(ci.plan_hash||'')},intent:{intent:'competitor_search',entities:{}},ctx:{conversation_id:String(ci.conversation_id||'')},plan:{sources:['website'],source:'website'}};}
var intent=inp.intent||{intent:(inp.request&&inp.request.intent)||'competitor_search',entities:inp.entities||{}};
var ctx=inp.ctx||{};
var dec=reuseDecision({intent:intent,ctx:ctx,cfg:cfg,now:(new Date()).toISOString()});
var rec=decisionRecord(dec,{agent_request_id:(inp.request&&inp.request.agent_request_id)||'req',conversation_id:ctx.conversation_id||'',intent:intent.intent,ts:(new Date()).toISOString()});
return [{json:Object.assign({},inp,{reuse_decision:dec,needs_external_call:dec.needs_external_call,orchestration_decision:rec,cfg:cfg})}];

// embedded n8n/lib/conversation_response.js (drift-proof; test asserts equality)
// conversation_response.js — Part 5: conversational response generation.
//
// Every reply must be useful WITHOUT buttons. The text explicitly states what was understood, what is missing,
// what will happen next, whether approval is needed, the expected source scope + call/budget ceiling, the
// current result, factual limitations, and a natural-language invitation to continue. Buttons (optional) are
// shortcuts whose callback_data maps to REAL router intents — they never add capabilities. Standalone +
// deterministic; user-facing text is Russian (operator preference).

function str(v) { return v == null ? '' : String(v).trim(); }
function num(v, d) { const n = Number(v); return isFinite(n) ? n : (d === undefined ? 0 : d); }

// Generic conversational reply skeleton — populated by the gateway from the routed intent + plan.
function buildConversationalReply(p) {
  p = p || {};
  const lines = [];
  if (p.understood) lines.push('Понял так: ' + str(p.understood));
  if (p.missing) lines.push('Не хватает: ' + str(p.missing));
  if (p.next) lines.push('Дальше: ' + str(p.next));
  if (p.requires_approval) lines.push('Нужно ваше подтверждение перед запуском (платные/внешние действия).');
  if (p.source_scope) lines.push('Источники: ' + str(p.source_scope));
  if (p.budget_ceiling) lines.push('Лимит вызовов/бюджет: ' + str(p.budget_ceiling));
  if (p.result) lines.push(str(p.result));
  if (p.limitations) lines.push('Ограничения: ' + str(p.limitations));
  const followups = (p.followups || []).map(str).filter(Boolean);
  if (followups.length) lines.push('Можно дальше: ' + followups.join('; ') + '. Просто напишите, что сделать.');
  return lines.join('\n');
}

// Clarification reply — exactly one concise question, with no external work implied.
function clarificationReply(question) {
  return str(question) || 'Уточните, пожалуйста, что сделать дальше?';
}

// Follow-up suggestions are drawn ONLY from currently-available capabilities (honest; never invents).
function followupSuggestions(availableCaps) {
  const names = (availableCaps || []).filter(c => c && c.available && ['deep_competitor_analysis', 'add_source', 'generate_ideas', 'compare_periods', 'manage_sources'].indexOf(c.id) >= 0).map(c => c.name);
  return names;
}

// Post-report conversational reply: factual summary -> changes -> ideas -> limitations -> NL invitation.
function postReportReply(report, availableCaps) {
  report = report || {};
  const lines = [];
  lines.push('Готово. ' + (str(report.summary_text) || ('Найдено записей в отчёте: ' + num(report.rows_after_filters || report.competitor_count, 0) + '.')));
  const changes = [].concat(report.changes || report.major_findings || []).map(str).filter(Boolean);
  if (changes.length) lines.push('Главное: ' + changes.join('; ') + '.');
  const ideas = [].concat(report.ideas || report.recommendations || []).map(str).filter(Boolean);
  if (ideas.length) lines.push('Идеи (это рекомендации, не факты): ' + ideas.slice(0, 5).join('; ') + '.');
  const limits = [].concat(report.limitations || []).map(str).filter(Boolean);
  if (limits.length) lines.push('Ограничения данных: ' + limits.join('; ') + '.');
  const sugg = followupSuggestions(availableCaps);
  if (sugg.length) {
    lines.push('Я могу: ' + sugg.join(', ') + ' — или найти новые каналы привлечения и подготовить идеи для вашего оффера. Просто напишите, что сделать дальше.');
  } else {
    lines.push('Напишите, что сделать дальше.');
  }
  return lines.join('\n');
}

// --- optional buttons (shortcuts only; callback_data maps to REAL router intents) --------------------------
function approvalButtons(agentRequestId) {
  return { inline_keyboard: [[
    { text: '✅ Запустить', callback_data: 'approve:' + str(agentRequestId) },
    { text: '✖ Отклонить', callback_data: 'reject:' + str(agentRequestId) }
  ]] };
}
// Each button's callback_data is `intent:<capability_id>` — the router parses these deterministically, so a
// button is exactly equivalent to typing the corresponding request. Only AVAILABLE capabilities are offered.
function actionButtons(availableCaps) {
  const wanted = ['deep_competitor_analysis', 'add_source', 'generate_ideas', 'compare_periods', 'manage_sources'];
  const rows = (availableCaps || []).filter(c => c && c.available && wanted.indexOf(c.id) >= 0)
    .map(c => [{ text: c.name, callback_data: 'intent:' + c.id }]);
  return rows.length ? { inline_keyboard: rows } : null;
}

// --- proactive post-report continuation (attached to the REAL delivery path) -------------------------------
// Conversational phrasing per capability for the proactive section. (Claude may rephrase, but the action set
// comes from the deterministic registry — never invented here.)
const PROACTIVE_LABELS = {
  deep_competitor_analysis: 'подробнее сравнить этих конкурентов',
  generate_ideas: 'предложить идеи для вашего оффера',
  add_source: 'добавить их источники в мониторинг',
  rerun_request: 'проверить изменения повторно',
  compare_periods: 'сравнить с прошлым периодом',
  manage_sources: 'настроить или проверить источники'
};
// State-aware action set, drawn ONLY from available capabilities. A success report offers the rich set; a
// partial/no-data report offers recovery actions instead of "success" actions.
function proactiveActions(state, availableCaps) {
  state = str(state).toLowerCase();
  const noData = state === 'no_data';
  const partial = state === 'partial';
  let wanted;
  if (noData) wanted = ['rerun_request', 'manage_sources', 'add_source'];
  else if (partial) wanted = ['rerun_request', 'generate_ideas', 'manage_sources', 'compare_periods'];
  else wanted = ['deep_competitor_analysis', 'generate_ideas', 'add_source', 'rerun_request', 'compare_periods'];
  const byId = {}; (availableCaps || []).forEach(c => { if (c) byId[c.id] = c; });
  return wanted.filter(id => byId[id] && byId[id].available).map(id => ({ id: id, label: PROACTIVE_LABELS[id] || (byId[id].name) }));
}
// The proactive sentence — useful WITHOUT buttons, ending with the natural-language invitation.
function proactiveText(state, availableCaps) {
  const acts = proactiveActions(state, availableCaps);
  if (!acts.length) return 'Напишите, что сделать дальше.';
  return 'Я могу ' + acts.map(a => a.label).join(', ') + '. Просто напишите, что сделать дальше.';
}
// Optional keyboard for the proactive actions (intent:<id> == the equivalent free-text request). Caller
// attaches this to the FINAL message chunk only.
function proactiveKeyboard(state, availableCaps) {
  const acts = proactiveActions(state, availableCaps);
  return acts.length ? { inline_keyboard: acts.map(a => [{ text: a.label, callback_data: 'intent:' + a.id }]) } : null;
}
// The full delivery body: IMMUTABLE report facts first (verbatim, never rewritten), then a state-aware
// proactive continuation. Partial/no-data get an honest one-line status before the continuation.
function deliveryBody(report, summary, availableCaps) {
  report = report || {}; summary = summary || {};
  const state = str(summary.final_state).toLowerCase() || 'completed';
  const noData = num(summary.records_reported, 0) === 0 && state !== 'completed';
  const facts = str(report.report_markdown) || str(report.summary_text) ||
    ('Итог: ' + (str(summary.final_state) || 'completed') + '. Записей в отчёте: ' + num(summary.records_reported, 0) + '.');
  const lines = [facts];
  if (noData || state === 'no_data') lines.push('Подходящих данных не собрано.');
  else if (state === 'partial') lines.push('Отчёт частичный — часть источников не отработала.');
  lines.push(proactiveText(noData ? 'no_data' : state, availableCaps));
  return lines.join('\n\n');
}
// --- end embedded conversation_response ---

// --- node driver ---
var inp=$json||{};var dec=inp.reuse_decision||{};
var chat=String((inp.request&&inp.request.chat_id)||'');
var text=buildConversationalReply({understood:(inp.intent&&inp.intent.intent)||'follow-up',result:'\u041e\u0442\u0432\u0435\u0447\u0430\u044e \u043f\u043e \u0443\u0436\u0435 \u0441\u043e\u0431\u0440\u0430\u043d\u043d\u044b\u043c \u0434\u0430\u043d\u043d\u044b\u043c (\u0431\u0435\u0437 \u043d\u043e\u0432\u044b\u0445 \u043f\u043b\u0430\u0442\u043d\u044b\u0445 \u0432\u044b\u0437\u043e\u0432\u043e\u0432). \u041f\u0440\u0438\u0447\u0438\u043d\u0430: '+(dec.reason||'reuse')+'.',next:'\u043c\u043e\u0433\u0443 \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u0438\u0442\u044c \u0438\u0434\u0435\u0438 \u0438\u043b\u0438 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435'});
var body={chat_id:chat,text:text};
return [{json:{telegram_send_body:JSON.stringify(body),reuse_reason:dec.reason}}];

// embedded n8n/lib/approval_gate.js (drift-proof; test asserts equality)
// approval_gate.js — Stage 4 approval & budget gate (B5).
//
// The single chokepoint every paid/external call passes through. It fails CLOSED: a call proceeds only
// when the request is approved, not cancelled, the source is allowlisted, item/call ceilings and the
// source + LLM budgets all hold, and this exact unit of work has not already been completed (idempotency
// key). A blocked gate returns a useful reason; it never throws and never leaks token values.

function str(v) { return v == null ? '' : String(v).trim(); }
function num(v, d) { const n = Number(v); return isFinite(n) ? n : d; }

const GATE_TERMINAL = ['completed', 'partial', 'failed', 'cancelled']; // local: avoids clash when co-embedded with agent_state.TERMINAL

// Deterministic idempotency key for one unit of external work (a source call within a request).
function idempotencyKey(agentRequestId, source, attempt) {
